package main

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"net/url"
	"sort"
	"strconv"
	"strings"
)

// mcp_matrix.json is GENERATED by scripts/gen_mcp_matrix.py from
// services/registry.json, providers/, core/pack_catalog.py, core/capabilities/ (per-service roll-ups),
// docker-compose.appliance.yml, .env.example and scripts/mcp_wiring.json. Regenerate it; never edit it by hand.
// Schema 2 adds per-home wiring (`homes`), capability roll-ups on each service and `v4_services`.
//
//go:embed mcp_matrix.json
var mcpMatrixJSON []byte

type mcpMatrix struct {
	Schema           int                  `json:"schema"`
	ApplianceVersion string               `json:"appliance_version"`
	Defaults         mcpDefaults          `json:"defaults"`
	HostPorts        map[string][]string  `json:"host_ports"`
	Settings         []mcpSetting         `json:"settings"`
	Clouds           map[string]*mcpCloud `json:"clouds"`
	Homes            map[string]*mcpHome  `json:"homes"`
	Scan             mcpScanConfig        `json:"scan"`
}

// mcpHome is one homes.<offline|nano|mesh> block: the client wiring for that kind of home.
type mcpHome struct {
	About        string                `json:"about,omitempty"`
	Source       string                `json:"source,omitempty"`
	SameAs       string                `json:"same_as,omitempty"`
	Clouds       map[string]*mcpWiring `json:"clouds"`
	ScanWarnings map[string]string     `json:"scan_warnings,omitempty"` // replaces scan.warnings for this home
}

type mcpDefaults struct {
	SimPort      int    `json:"sim_port"`
	TLSPort      int    `json:"tls_port"`
	Host         string `json:"host"`
	AzureAccount string `json:"azure_account"`
}

type mcpSetting struct {
	Name         string `json:"name"`
	Default      string `json:"default"`
	Doc          string `json:"doc"`
	CommentedOut bool   `json:"commented_out"`
}

type mcpCloud struct {
	DisplayName    string                     `json:"display_name"`
	NativeServices json.RawMessage            `json:"native_services,omitempty"`
	Services       []mcpService               `json:"services"`
	V4Services     []mcpService               `json:"v4_services"`
	Tools          map[string]json.RawMessage `json:"tools"`
	Wiring         mcpWiring                  `json:"wiring"`
}

type mcpService struct {
	ID         string   `json:"id"`
	Name       string   `json:"name"`
	Status     string   `json:"status"` // from services/registry.json, e.g. "released"
	ReleasedIn string   `json:"released_in,omitempty"`
	Summary    string   `json:"summary,omitempty"`
	PackID     string   `json:"pack_id,omitempty"`
	Actions    []string `json:"actions,omitempty"`
	DataPlane  string   `json:"data_plane,omitempty"`
	Protocol   string   `json:"protocol,omitempty"`
	// Knowledge v2: roll-up of the service's capabilities in core/capabilities (scripts/gen_mcp_matrix.py _rollup).
	CapabilityService string                    `json:"capability_service,omitempty"`
	Capabilities      int                       `json:"capabilities,omitempty"`
	Levels            map[string]string         `json:"levels,omitempty"`
	LevelCounts       map[string]map[string]int `json:"level_counts,omitempty"`
	Tier              string                    `json:"tier,omitempty"`
	Mesh              bool                      `json:"mesh,omitempty"`
	MeshOnly          []string                  `json:"mesh_only,omitempty"`
	ProCapabilities   int                       `json:"pro_capabilities,omitempty"`
}

type mcpWiring struct {
	Env           []mcpEnvVar      `json:"env"`
	Unavailable   []mcpUnavailable `json:"unavailable,omitempty"`
	Notes         []string         `json:"notes"`
	Terraform     string           `json:"terraform"`
	TerraformNote string           `json:"terraform_note,omitempty"`
}

type mcpEnvVar struct {
	Name     string `json:"name"`
	Value    string `json:"value"`
	Note     string `json:"note,omitempty"`
	Verified *bool  `json:"verified,omitempty"` // homes.nano: whether D0 exercised the value on Nano
}

// mcpUnavailable is a setting an SDK cannot use in a home (e.g. Key Vault through the plain-HTTP Nano tunnel):
// the MCP never hands out a value for it, only the warning.
type mcpUnavailable struct {
	Name    string `json:"name"`
	SDK     string `json:"sdk,omitempty"`
	Warning string `json:"warning"`
}

type mcpScanRule struct {
	Cloud   string `json:"cloud"`
	Lang    string `json:"lang"`
	Pattern string `json:"pattern"`
}

type mcpScanConfig struct {
	SkipDirs     []string                     `json:"skip_dirs"`
	Extensions   []string                     `json:"extensions"`
	Rules        []mcpScanRule                `json:"rules"`
	AlreadyWired string                       `json:"already_wired"`
	Aliases      map[string]map[string]string `json:"aliases"`
	Warnings     map[string]string            `json:"warnings"`
}

var mcpClouds = []string{"aws", "gcp", "azure"}

// mcpMatrixSchema is the knowledge schema this binary reads (scripts/gen_mcp_matrix.py SCHEMA).
const mcpMatrixSchema = 2

func loadMCPMatrix() (*mcpMatrix, error) {
	var m mcpMatrix
	if err := json.Unmarshal(mcpMatrixJSON, &m); err != nil {
		return nil, fmt.Errorf("embedded mcp_matrix.json is invalid (regenerate with scripts/gen_mcp_matrix.py): %w", err)
	}
	if m.Schema != mcpMatrixSchema {
		return nil, fmt.Errorf("embedded mcp_matrix.json has schema %d; this binary understands schema %d", m.Schema, mcpMatrixSchema)
	}
	for _, c := range mcpClouds {
		if m.Clouds[c] == nil {
			return nil, fmt.Errorf("embedded mcp_matrix.json is missing cloud %q", c)
		}
		for _, h := range []string{"offline", "nano", "mesh"} {
			if m.Homes[h] == nil || m.Homes[h].Clouds[c] == nil {
				return nil, fmt.Errorf("embedded mcp_matrix.json is missing homes.%s.clouds.%s", h, c)
			}
		}
	}
	if m.Defaults.SimPort == 0 {
		m.Defaults.SimPort = 9000
	}
	if m.Defaults.TLSPort == 0 {
		m.Defaults.TLSPort = 9443
	}
	if m.Defaults.Host == "" {
		m.Defaults.Host = "127.0.0.1"
	}
	if m.Defaults.AzureAccount == "" {
		m.Defaults.AzureAccount = "devstoreaccount1"
	}
	return &m, nil
}

// service finds a released (registry) service, then a v4 service (core/capabilities only, status "v4").
func (m *mcpMatrix) service(cloud, id string) *mcpService {
	c := m.Clouds[cloud]
	if c == nil {
		return nil
	}
	for i := range c.Services {
		if c.Services[i].ID == id {
			return &c.Services[i]
		}
	}
	for i := range c.V4Services {
		if c.V4Services[i].ID == id {
			return &c.V4Services[i]
		}
	}
	return nil
}

// emulated: a registry release, or a v4 service from the capability registry.
func emulated(status string) bool { return status == "released" || status == "v4" }

// mcpTarget is where the simulator is reachable from the developer's machine.
type mcpTarget struct {
	Scheme  string
	Host    string
	SimPort int // 0: the scheme's default port (e.g. https://relay.vyomi.cloud/<session>)
	TLSPort int // 0: no TLS endpoint (Nano)
	Account string
	Path    string // base path, e.g. the cloud relay's /<session>
}

type mcpTargetArgs struct {
	Host    string `json:"host"`
	Account string `json:"account"`
}

// target resolves the endpoint: tool args > VYOMI_ENDPOINT > VYOMI_SIMULATOR_PORT > defaults.
func (s *mcpServer) target(a *mcpTargetArgs) mcpTarget {
	t := mcpTarget{
		Scheme:  "http",
		Host:    s.matrix.Defaults.Host,
		SimPort: s.matrix.Defaults.SimPort,
		TLSPort: s.matrix.Defaults.TLSPort,
		Account: s.matrix.Defaults.AzureAccount,
	}
	if p, err := strconv.Atoi(envAny("", "VYOMI_SIMULATOR_PORT", "CLOUDLEARN_SIMULATOR_PORT")); err == nil && p > 0 {
		t.SimPort = p
	}
	if ep := envAny("", "VYOMI_ENDPOINT"); ep != "" {
		if u, err := url.Parse(ep); err == nil && u.Hostname() != "" {
			if u.Scheme != "" {
				t.Scheme = u.Scheme
			}
			t.Host = u.Hostname()
			if p, err := strconv.Atoi(u.Port()); err == nil {
				t.SimPort = p
			}
		}
	}
	if a != nil {
		if h := strings.TrimSpace(a.Host); h != "" {
			if hh, pp, ok := strings.Cut(h, ":"); ok {
				h = hh
				if p, err := strconv.Atoi(pp); err == nil {
					t.SimPort = p
				}
			}
			t.Host = h
		}
		if acc := strings.TrimSpace(a.Account); acc != "" {
			t.Account = acc
		}
	}
	return t
}

func (t mcpTarget) simURL() string { return t.Scheme + "://" + t.hostPort() + t.Path }

func (t mcpTarget) hostPort() string {
	if t.SimPort == 0 {
		return t.Host
	}
	return fmt.Sprintf("%s:%d", t.Host, t.SimPort)
}

func (t mcpTarget) render(s string) string {
	return strings.NewReplacer(
		"{sim}", t.simURL(),
		"{sim_hostport}", t.hostPort(),
		"{sim_port}", strconv.Itoa(t.SimPort),
		"{tls_hostport}", fmt.Sprintf("%s:%d", t.Host, t.TLSPort),
		"{tls_port}", strconv.Itoa(t.TLSPort),
		"{host}", t.Host,
		"{account}", t.Account,
		// providers/*.py tool_response() hard-codes the default endpoint.
		"http://127.0.0.1:9000", t.simURL(),
	).Replace(s)
}

// wiring is a cloud's client wiring for a home (homes.<offline|nano|mesh> in the knowledge).
func (s *mcpServer) wiring(cloud, homeID string) *mcpWiring {
	if h := s.matrix.Homes[wiringHome(homeID)]; h != nil && h.Clouds[cloud] != nil {
		return h.Clouds[cloud]
	}
	return &s.matrix.Clouds[cloud].Wiring
}

// envVars renders a cloud's wiring env block for this home and target, with the warnings for what the home
// cannot serve. Nano has no TLS endpoint: a value that needs one is never handed out (spec decision 8);
// homes.nano lists such settings under `unavailable` with the reason D0 found.
func (s *mcpServer) envVars(cloud, homeID string, t mcpTarget) ([]mcpEnvVar, []string) {
	w := s.wiring(cloud, homeID)
	nano := wiringHome(homeID) == "nano"
	out := make([]mcpEnvVar, 0, len(w.Env))
	var warns []string
	for _, v := range w.Env {
		val, note := v.Value, v.Note
		if nano && strings.Contains(val, "{tls_") {
			warns = append(warns, v.Name+" needs TLS; not available through the Nano tunnel. Use a mesh, or see vyomi_capability.")
			continue
		}
		if homeID == homeNanoCloud {
			// The cloud relay is one HTTPS URL: no *.localtest.me host routing, no AMQP / TCP (local tunnel only).
			val = strings.ReplaceAll(val, "http://{account}.queue.localtest.me:{sim_port}", "{sim}/{account}")
			if strings.HasPrefix(val, "Endpoint=sb://") {
				warns = append(warns, v.Name+": Service Bus AMQP needs the local tunnel (vyomi-tunnel); the cloud relay carries HTTP only.")
				continue
			}
		}
		out = append(out, mcpEnvVar{Name: v.Name, Value: t.render(val), Note: t.render(note), Verified: v.Verified})
	}
	for _, u := range w.Unavailable {
		warns = append(warns, u.Name+": "+t.render(u.Warning))
	}
	if homeID == homeNanoCloud {
		warns = append(warns, "Cloud relay: the values follow the local-tunnel findings (D0) and were not verified through the relay; payload caps apply. The local tunnel (vyomi-tunnel) is faster and has no caps.")
	}
	return out, warns
}

// formatEnv renders env vars as dotenv | shell | powershell text.
func formatEnv(cloud string, vars []mcpEnvVar, format string) string {
	var b strings.Builder
	switch format {
	case "shell":
		fmt.Fprintf(&b, "# Vyomi: %s\n", strings.ToUpper(cloud))
		for _, v := range vars {
			fmt.Fprintf(&b, "export %s=%s\n", v.Name, shellQuote(v.Value))
		}
	case "powershell":
		fmt.Fprintf(&b, "# Vyomi: %s\n", strings.ToUpper(cloud))
		for _, v := range vars {
			fmt.Fprintf(&b, "$env:%s = '%s'\n", v.Name, strings.ReplaceAll(v.Value, "'", "''"))
		}
	default: // dotenv
		fmt.Fprintf(&b, "# Vyomi: %s\n", strings.ToUpper(cloud))
		for _, v := range vars {
			if v.Note != "" {
				fmt.Fprintf(&b, "# %s\n", v.Note)
			}
			val := v.Value
			if strings.ContainsAny(val, " #;\"'") || val == "" {
				val = `"` + strings.ReplaceAll(val, `"`, `\"`) + `"`
			}
			fmt.Fprintf(&b, "%s=%s\n", v.Name, val)
		}
	}
	return b.String()
}

func shellQuote(s string) string {
	if s == "" {
		return "''"
	}
	if !strings.ContainsAny(s, " \t\n'\"\\$`;&|<>(){}*?!#~") {
		return s
	}
	return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'"
}

func statusCounts(svcs []mcpService) map[string]int {
	out := map[string]int{}
	for _, s := range svcs {
		out[s.Status]++
	}
	return out
}

func sortedKeys[V any](m map[string]V) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}
